async function getAnyChannelVideos(url) {
  await tool.navigate({ tabId: 2017691829, url });
  await tool.wait_for({ tabId: 2017691829, condition: "dom_settled", timeout_ms: 4000 });

  return await browserjs(2017691829, () => {
    const anchors = Array.from(document.querySelectorAll('a[href*="/watch?v="]'));
    const seen = new Set();
    const list = [];
    for (const a of anchors) {
      const href = a.href.split('&')[0];
      if (seen.has(href)) continue;

      // Let's get title: either from a.innerText or aria-label or child
      let title = a.innerText.trim();
      if (!title || /^\d+:\d+$/.test(title)) {
        title = a.getAttribute('aria-label') || a.getAttribute('title') || "";
      }

      // Look up parent container text
      let meta = "";
      const parent = a.closest('ytd-rich-item-renderer, ytd-grid-video-renderer, ytd-video-renderer, .yt-lockup-view-model, div#content');
      if (parent) {
        const lines = parent.innerText.split('\n').map(x => x.trim()).filter(Boolean);
        meta = lines.filter(x => x.includes('ago') || x.includes('views')).join(' • ');
        if (!title || /^\d+:\d+$/.test(title)) {
          // Check lines for a possible title
          const candidates = lines.filter(x => !/^\d+:\d+$/.test(x) && !x.includes('views') && !x.includes('ago') && x.length > 5);
          if (candidates.length > 0) title = candidates[0];
        }
      }

      if (title && !/^\d+:\d+$/.test(title) && href) {
        seen.add(href);
        list.push({ title, href, meta });
      }
    }
    return {
      channelTitle: document.title.replace(" - YouTube", "").trim(),
      videos: list.slice(0, 10)
    };
  });
}

