// Let's inspect channel URLs and their recent videos
const channels = [
  "https://www.youtube.com/@mkbhd/videos",
  "https://www.youtube.com/@Dave2D/videos",
  "https://www.youtube.com/@JustJoshTech/videos",
  "https://www.youtube.com/@Mrwhosetheboss/videos",
  "https://www.youtube.com/@TheVerge/videos",
  "https://www.youtube.com/@LinusTechTips/videos",
  "https://www.youtube.com/@JarrodsTech/videos"
];

const channelData = [];

for (const chUrl of channels) {
  await tool.navigate({ tabId: 2017691829, url: chUrl });
  await tool.wait_for({ tabId: 2017691829, condition: "dom_settled", timeout_ms: 4000 });

  const data = await browserjs(2017691829, () => {
    const channelName = document.querySelector('yt-dynamic-sizing-formatted-string#text, #channel-header #text, ytd-channel-name yt-formatted-string')?.textContent?.trim() || document.title;
    const vids = Array.from(document.querySelectorAll('ytd-rich-item-renderer, ytd-grid-video-renderer')).slice(0, 5).map(v => {
      const a = v.querySelector('#video-title-link, a#video-title');
      const meta = v.querySelector('#metadata-line')?.textContent?.trim().replace(/\s+/g, ' ');
      return {
        title: a?.textContent?.trim() || a?.getAttribute('title'),
        url: a?.href,
        metadata: meta
      };
    }).filter(v => v.title && v.url);
    return { channelName, vids };
  });
  channelData.push({ url: chUrl, ...data });
}

console.log("Channel data collected:\n", JSON.stringify(channelData, null, 2));

