const targetChannels = [
  { handle: "@mkbhd", name: "Marques Brownlee", url: "https://www.youtube.com/@mkbhd/videos" },
  { handle: "@Dave2D", name: "Dave2D", url: "https://www.youtube.com/@Dave2D/videos" },
  { handle: "@JustJoshTech", name: "Just Josh", url: "https://www.youtube.com/@JustJoshTech/videos" },
  { handle: "@Mrwhosetheboss", name: "Mrwhosetheboss", url: "https://www.youtube.com/@Mrwhosetheboss/videos" },
  { handle: "@TheVerge", name: "The Verge", url: "https://www.youtube.com/@TheVerge/videos" },
  { handle: "@LinusTechTips", name: "Linus Tech Tips", url: "https://www.youtube.com/@LinusTechTips/videos" },
  { handle: "@JarrodsTech", name: "Jarrod'sTech", url: "https://www.youtube.com/@JarrodsTech/videos" }
];

const results = [];

for (const ch of targetChannels) {
  await tool.navigate({ tabId: 2017691829, url: ch.url });
  await tool.wait_for({ tabId: 2017691829, condition: "dom_settled", timeout_ms: 4000 });

  const vids = await browserjs(2017691829, () => {
    // In YouTube rich-grid, items have #video-title and metadata
    const items = Array.from(document.querySelectorAll('ytd-rich-item-renderer'));
    return items.slice(0, 6).map(it => {
      const titleLink = it.querySelector('a#video-title-link, a#video-title');
      const metaSpans = Array.from(it.querySelectorAll('#metadata-line span')).map(s => s.innerText.trim());
      return {
        title: titleLink?.innerText?.trim() || titleLink?.getAttribute('title'),
        url: titleLink?.href,
        metadata: metaSpans.join(' • ')
      };
    }).filter(v => v.title && v.url);
  });

  results.push({ ...ch, vids });
}

console.log("Scraped channel videos:", JSON.stringify(results, null, 2));

