async function extractChannelVideos(url) {
  await tool.navigate({ tabId: 2017691829, url });
  await tool.wait_for({ tabId: 2017691829, condition: "dom_settled", timeout_ms: 4000 });

  return await browserjs(2017691829, () => {
    const channelTitle = document.title.replace(" - YouTube", "").trim();
    const seen = new Set();
    const list = [];

    // Find all links containing /watch?v=
    const anchors = Array.from(document.querySelectorAll('a[href*="/watch?v="]'));
    for (const a of anchors) {
      let title = a.innerText.trim();
      const aria = a.getAttribute('aria-label');
      // If title is just duration like "16:36", ignore or use aria-label
      if (/^\d+:\d+(:\d+)?$/.test(title) || !title) {
        if (aria) {
          // aria-label often looks like: "iPhone 18 Pro Review: All About that Chip 16 minutes"
          title = aria.replace(/\s+\d+\s*(minutes?|seconds?|hours?|views?).*$/i, '').trim();
        }
      }
      const href = a.href.split('&')[0]; // clean tracking
      if (title && href && !seen.has(href) && title.length > 5 && !/^\d+:\d+$/.test(title)) {
        seen.add(href);
        // let's find metadata container
        let meta = "";
        const parent = a.closest('ytd-rich-item-renderer, ytd-grid-video-renderer, ytd-video-renderer, .yt-lockup-view-model');
        if (parent) {
          meta = parent.innerText.split('\n').filter(t => t.includes('ago') || t.includes('views')).join(' • ');
        }
        list.push({ title, href, meta });
      }
    }
    return { channelTitle, list };
  });
}

