const videos = [
  { id: "dave2d_iphone18", url: "https://www.youtube.com/watch?v=eHYaESEzFHc" },
  { id: "verge_iphone18", url: "https://www.youtube.com/watch?v=4EE7D3XgaYw" },
  { id: "mrwho_iphone18", url: "https://www.youtube.com/watch?v=5pV3D14y1FQ" }
];

const results = {};

for (const v of videos) {
  await tool.navigate({ tabId: 2017691829, url: v.url });
  await tool.wait_for({ tabId: 2017691829, condition: "dom_settled", timeout_ms: 3500 });

  const data = await browserjs(2017691829, async () => {
    // Expand description
    const expander = document.querySelector('tp-yt-paper-button#expand, #expand, #description-inline-expander');
    if (expander) expander.click();

    // Try opening transcript
    const btn = Array.from(document.querySelectorAll('button')).find(b => b.innerText.toLowerCase().includes('transcript'));
    if (btn) btn.click();
    await new Promise(r => setTimeout(r, 1500));

    const panel = Array.from(document.querySelectorAll('ytd-engagement-panel-section-list-renderer')).find(p => p.getAttribute('visibility') === 'ENGAGEMENT_PANEL_VISIBILITY_EXPANDED' || p.innerText.includes('Search transcript'));

    const titleEl = document.querySelector('h1.ytd-watch-metadata yt-formatted-string, #title h1 yt-formatted-string');
    const title = titleEl ? titleEl.innerText.trim() : document.title.replace(" - YouTube", "").trim();
    const chEl = document.querySelector('#owner #channel-name a, ytd-channel-name #text');
    const channelName = chEl ? chEl.innerText.trim() : "";
    const infoContainer = document.querySelector('#info-container, #description-inline-expander, #formatted-snippet-text');
    const infoText = infoContainer ? infoContainer.innerText.trim() : "";

    return {
      title,
      channelName,
      infoText,
      transcriptSnippet: panel ? panel.innerText.slice(0, 3000) : "",
      transcriptTotalLen: panel ? panel.innerText.length : 0,
      transcriptTail: panel ? panel.innerText.slice(-2000) : ""
    };
  });

  results[v.id] = data;
}

console.log("Batch 1 results:", JSON.stringify(results, null, 2));
await write("tmp://batch1_transcripts.json", JSON.stringify(results, null, 2), "application/json");

